import base64, zlib, hashlib, subprocess, json
from pathlib import Path
payload = ''''''
patch = zlib.decompress(base64.b64decode(payload))
assert hashlib.sha256(patch).hexdigest() == '2b5b447b0524870ad642a66f8de36f91b94bcabfa8a473ab96930b6cf9940180'
subprocess.run(['git','apply','--check','-'], input=patch, check=True)
subprocess.run(['git','apply','-'], input=patch, check=True)
p = Path('package.json')
data = json.loads(p.read_text())
assert 'check:messenger-navigation' not in data['scripts']
data['scripts']['check:messenger-navigation'] = 'node --no-warnings --experimental-strip-types checks/messenger-navigation-runtime.cjs && node --no-warnings --experimental-strip-types checks/messenger-pin-focus.mjs'
data['scripts']['check'] += ' && npm run check:messenger-navigation'
p.write_text(json.dumps(data, indent=2, ensure_ascii=False)+'\n')
p = Path('docs/CHAT_PINNING.md')
p.write_text(p.read_text()+'''\n## Ошибка перехода не является ошибкой синхронизации\n\nОшибки открытия сообщения отображаются отдельным закрываемым уведомлением.\nПереход не устанавливает и не очищает syncError: настоящие ошибки синхронизации\nсохраняются до исправления соответствующим механизмом обмена данными.\n\nПодтверждение фокуса использует measureInWindow нативной строки и контейнера\nленты, а не только onViewableItemsChanged. У измерения есть ограничение времени;\nсвежая viewability используется лишь при отсутствии измерения. Фактически\nневидимое сообщение не считается открытым. Индекс берётся из данных FlatList\nпосле commit, с учётом скрытых удалённых сообщений в Избранном и фильтра автора.\nПри задержке рендера запрос повторяется, устаревший retry отменяется. Автоподгрузка\nграниц и maintainVisibleContentPosition не конкурируют с явным переходом.\n\nЛокальные диагностические события message.navigation.started / focused /\nfocus_timeout / failed содержат ID цели, платформу, число попыток и геометрию,\nбез текста сообщения, медиа, токенов и отправки этих данных в AppMetrica.\nРучная прокрутка и выход отменяют ожидание без сообщения об ошибке.\nПроверка реальных callback-функций экрана с подменёнными native/SQLite/network:\n`npm run check:messenger-navigation`. Реальное устройство отдельно не проверено.\n''')
